using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool Definitions ---

var notes = new List<string>();

[Description("Search the web for information on a given query. Returns relevant search results.")]
string WebSearch(string query)
{
    Console.WriteLine($"  [Tool] Searching the web for: \"{query}\"");
    // Simulated search results for demonstration purposes.
    // In production, integrate with Bing Search API or similar.
    var results = query.ToLowerInvariant() switch
    {
        var q when q.Contains("quantum computing") =>
            """
            1. Quantum computing uses qubits that can exist in superposition, enabling parallel computation.
            2. Major players include IBM (127-qubit Eagle), Google (Sycamore), and IonQ (trapped-ion approach).
            3. Key applications: cryptography, drug discovery, optimization problems, and materials science.
            4. Current challenges: decoherence, error correction, and scaling qubit counts.
            5. IBM aims for 100,000-qubit systems by 2033.
            """,
        var q when q.Contains("artificial intelligence") || q.Contains(" ai ") =>
            """
            1. AI encompasses machine learning, deep learning, NLP, and computer vision.
            2. Large language models (LLMs) like GPT-4 have transformed natural language understanding.
            3. AI is being applied in healthcare, finance, autonomous vehicles, and scientific research.
            4. Concerns include bias, job displacement, safety, and alignment with human values.
            5. Global AI market projected to reach $1.8 trillion by 2030.
            """,
        _ =>
            $"""
            1. "{query}" is an active area of research with growing interest.
            2. Recent publications show advancements in both theory and practical applications.
            3. Industry adoption is increasing, with several startups and enterprises investing heavily.
            4. Open-source communities are contributing tools and frameworks.
            5. Experts predict significant breakthroughs in the next 5-10 years.
            """
    };
    return results;
}

[Description("Save a research note for later use in the summary. Use this to record key findings.")]
string TakeNote(string note)
{
    notes.Add(note);
    Console.WriteLine($"  [Tool] Note saved ({notes.Count} total)");
    return $"Note saved successfully. You now have {notes.Count} note(s).";
}

[Description("Retrieve all saved research notes.")]
string GetNotes()
{
    if (notes.Count == 0)
        return "No notes saved yet.";
    return string.Join("\n", notes.Select((n, i) => $"{i + 1}. {n}"));
}

// --- Agent Setup ---

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-api-key-here";
var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

var openAiClient = new OpenAIClient(apiKey);
IChatClient chatClient = openAiClient.GetChatClient(modelId).AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearch),
        AIFunctionFactory.Create(TakeNote),
        AIFunctionFactory.Create(GetNotes),
    ]
};

// --- Run the Research Agent ---

Console.WriteLine("=== AI Research Agent ===\n");
Console.Write("Enter a research topic (or press Enter for 'quantum computing'): ");
var topic = Console.ReadLine();
if (string.IsNullOrWhiteSpace(topic))
    topic = "quantum computing";

Console.WriteLine($"\nResearching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System,
        """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information (make multiple searches with different queries)
        2. Taking notes on key findings as you discover them
        3. After gathering enough information, retrieve your notes and provide a well-structured summary

        Always take notes on important findings before moving to the next search.
        When you have enough information, provide a final comprehensive summary.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

var response = await chatClient.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n=== Research Summary ===\n");
Console.WriteLine(response.Text);

if (notes.Count > 0)
{
    Console.WriteLine("\n=== Saved Notes ===\n");
    for (int i = 0; i < notes.Count; i++)
        Console.WriteLine($"  {i + 1}. {notes[i]}");
}

Console.WriteLine("\nDone.");

